TypeScript (browser/node) reference:

// Minimal bridge that consumes framed fragments and yields assembled JSON events
interface FragEnvelope { t: string; s: number; id: string; b?: string; p?: string }
async function* consumeFramedStream(stream: ReadableStream<Uint8Array>) {
  const reader = stream.getReader();
  let buffer = '';
  const partials = new Map<string, {buf: string[], expected?: number}>();
  while (true) {
    const {done, value} = await reader.read();
    if (done) break;
    buffer += new TextDecoder().decode(value);
    let idx;
    while ((idx = buffer.indexOf('\n')) >= 0) {
      const line = buffer.slice(0, idx);
      buffer = buffer.slice(idx + 1);
      if (!line) continue;
      const env: FragEnvelope = JSON.parse(line);
      const id = env.id;
      if (!partials.has(id)) partials.set(id, {buf: []});
      const slot = partials.get(id)!;
      slot.buf[env.s] = env.b ? atob(env.b) : '';
      if (env.t === 'end') {
        const joined = slot.buf.join('');
        yield {id, payload: JSON.parse(joined)};
        partials.delete(id);
      }
    }
  }
}

// Usage: for await (const msg of consumeFramedStream(resp.body)) { /* handle msg.payload */ }

Go (channel-style consumer) reference:

// Compact consumer that reads framed newline JSON and emits completed objects over a channel
package bridge
import (
  "bufio"
  "encoding/base64"
  "encoding/json"
  "net/http"
)

type Envelope struct { T string `json:"t"`; S int `json:"s"`; ID string `json:"id"`; B string `json:"b,omitempty"` }

func ConsumeFramed(resp *http.Response) (<-chan map[string]interface{}, <-chan error) {
  out := make(chan map[string]interface{})
  errs := make(chan error, 1)
  go func() {
    defer close(out); defer close(errs)
    scanner := bufio.NewScanner(resp.Body)
    partials := map[string]map[int]string{}
    for scanner.Scan() {
      var e Envelope
      if err := json.Unmarshal(scanner.Bytes(), &e); err != nil { errs <- err; return }
      if _, ok := partials[e.ID]; !ok { partials[e.ID] = map[int]string{} }
      partials[e.ID][e.S] = e.B
      if e.T == "end" {
        // join in order
        // NOTE: small allocation, acceptable for typical fragment counts
        var parts []byte
        for i := 0; ; i++ {
          if p, ok := partials[e.ID][i]; ok {
            decoded, _ := base64.StdEncoding.DecodeString(p)
            parts = append(parts, decoded...)
          } else { break }
        }
        var obj map[string]interface{}
        json.Unmarshal(parts, &obj)
        out <- obj
        delete(partials, e.ID)
      }
    }
    if err := scanner.Err(); err != nil { errs <- err }
  }()
  return out, errs
}
